"""write_report spine: JSON rows, one per ticker, sorted."""

from __future__ import annotations

import json

import pytest

from risk import Drawdown, TickerSummary
from risk.report import write_report


def _summary(ticker: str, last_vol: float | None = 0.5) -> TickerSummary:
    return TickerSummary(
        ticker=ticker, ann_return=0.1, ann_vol=0.2, sharpe=0.5, last_vol=last_vol
    )


def _drawdown(ticker: str, depth: float = -0.1) -> Drawdown:
    return Drawdown(
        ticker=ticker, depth=depth, peak_date="2024-01-02", trough_date="2024-01-05"
    )


def test_sample_writes_one_row_with_drawdown(contract_sample, tmp_path):
    summary = TickerSummary(**contract_sample("risk.TickerSummary"))
    drawdown = Drawdown(**contract_sample("risk.Drawdown"))
    out = tmp_path / "risk_report.json"
    report = write_report([summary], [drawdown], out)
    expected_row = contract_sample("risk.Report")["rows"][0]
    assert report.path == str(out)
    assert report.rows == (expected_row,)
    assert json.loads(out.read_text()) == {"tickers": [expected_row]}


def test_rows_sorted_by_ticker_and_paired_by_ticker(tmp_path):
    out = tmp_path / "r.json"
    report = write_report(
        [_summary("C"), _summary("A", None)],
        [_drawdown("A", -0.3), _drawdown("C", -0.7)],
        out,
    )
    assert [r["ticker"] for r in report.rows] == ["A", "C"]
    assert report.rows[0]["max_drawdown"] == -0.3
    assert report.rows[0]["last_vol"] is None
    assert report.rows[1]["max_drawdown"] == -0.7
    assert json.loads(out.read_text())["tickers"] == list(report.rows)


@pytest.mark.parametrize(
    ("summary_tickers", "drawdown_tickers"),
    [(["A"], ["B"]), (["A", "B"], ["A"]), (["A"], ["A", "A"])],
)
def test_different_tickers_raise(tmp_path, summary_tickers, drawdown_tickers):
    with pytest.raises(ValueError, match="different tickers"):
        write_report(
            [_summary(t) for t in summary_tickers],
            [_drawdown(t) for t in drawdown_tickers],
            tmp_path / "r.json",
        )

